   function cfSummaryHTML(c){const fi=contractFinanceInfo(c),purchases=(purchaseInvoices||[]).filter(x=>x.contractId===c.id),expenses=(contractExpenses||[]).filter(x=>x.contractId===c.id),pur=purchases.reduce((s,x)=>s+Number(x.total||0),0),exp=expenses.reduce((s,x)=>s+Number(x.amount||0),0),net=fi.paid-pur-exp;return `<div class="stats-grid"><div class="stat-card"><small>إجمالي العقد</small><b>${money(c.value)}</b></div><div class="stat-card"><small>المحصل</small><b>${money(fi.paid)}</b></div><div class="stat-card"><small>المتبقي</small><b>${money(fi.remaining)}</b></div><div class="stat-card"><small>المتأخر</small><b>${money(fi.overdue)}</b></div><div class="stat-card"><small>المشتريات</small><b>${money(pur)}</b></div><div class="stat-card"><small>المصروفات</small><b>${money(exp)}</b></div><div class="stat-card"><small>مؤشر التدفق (محصل - تكاليف)</small><b style="color:${net>=0?'#3c8b70':'#c85c59'}">${money(net)}</b></div></div><div class="quick-grid" style="margin-top:12px"><button class="quick-card" data-cf-tab="payments"><b>إدارة الدفعات</b><small>تسجيل الدفعات ومراحل التركيب</small></button><button class="quick-card" data-cf-tab="purchases"><b>فواتير المشتريات</b><small>ربط فواتير الموردين بالعقد</small></button><button class="quick-card" data-cf-tab="expenses"><b>مصروفات العقد</b><small>تسجيل مصروفات مباشرة للعقد</small></button><button class="quick-card" data-cf-tab="profit"><b>المؤشر التشغيلي</b><small>مؤشر إداري وليس صافي ربح محاسبياً</small></button></div>`}
