  function enhanceContractBatchForm(f){if(!f||f.dataset.form!=="contract"||f.dataset.batchReady)return;f.dataset.batchReady="1";const value=f.querySelector('[name="value"]');if(value){const label=value.closest("label");if(label?.firstChild)label.firstChild.textContent="قيمة العقد الأول"}const buildingLegend=f.querySelector('[data-buildings]')?.closest("fieldset")?.querySelector("legend");if(buildingLegend)buildingLegend.textContent="مباني العقد الأول";const typeLabel=f.querySelector('[name="type"]')?.closest("label");typeLabel?.insertAdjacentHTML("beforebegin",'<label>عدد العقود المطلوبة<input name="contractCount" type="number" min="1" max="10" step="1" value="1" required></label><div class="contract-shared-options" data-contract-shared-options hidden><b>البيانات المتماثلة بين العقود</b><label><input type="checkbox" name="sharedSpecs"> إدخال المواصفات مرة واحدة لجميع العقود</label><label><input type="checkbox" name="sharedMaintenance"> إدخال بنود الصيانة مرة واحدة لجميع العقود</label></div>');const panels=$$("[data-contract-tab-panel]",f);panels.forEach((panel,index)=>panel.insertAdjacentHTML("beforeend",`<div data-contract-batch-panel="${index}"></div>`));const count=f.querySelector('[name="contractCount"]'),options=$('[data-contract-shared-options]',f),sharedSpecs=$('[name="sharedSpecs"]',f),sharedMaintenance=$('[name="sharedMaintenance"]',f);const syncShared=()=>{$$("[data-shared-spec-fields]",f).forEach(x=>x.hidden=sharedSpecs.checked);$$("[data-shared-maintenance-fields]",f).forEach(x=>x.hidden=sharedMaintenance.checked)};const renderUnits=()=>{const n=Math.max(1,Math.min(10,Number(count.value)||1));count.value=n;options.hidden=n===1;if(n===1){sharedSpecs.checked=false;sharedMaintenance.checked=false}panels.forEach((panel,index)=>{$(`[data-contract-batch-panel="${index}"]`,panel).innerHTML=Array.from({length:n-1},(_,idx)=>contractBatchPanel(idx+2,index)).join("")});syncShared();updateContractTypeFields(f)};count.addEventListener("input",renderUnits);sharedSpecs.addEventListener("change",syncShared);sharedMaintenance.addEventListener("change",syncShared);renderUnits()}
  const baseContractElements=(f,selector)=>$$(selector,f).filter(el=>!el.closest(".contract-batch-unit"));
  const collectBaseContractSpecs=f=>Object.assign({},specDefaults,...baseContractElements(f,"[name^='spec_']").map(el=>({[el.name.replace(/^spec_/,"")]:el.value})));
  const collectBaseContractBuildings=b=>baseContractElements(b,".building-row").map(r=>({name:$('[name="buildingName"]',r)?.value.trim()||"",district:$('[name="buildingDistrict"]',r)?.value.trim()||"",buildingNumber:$('[name="buildingNumber"]',r)?.value.trim()||"",mapUrl:$('[name="buildingMapUrl"]',r)?.value.trim()||"",guardMobile:$('[name="buildingGuardMobile"]',r)?.value.trim()||""})).filter(b=>b.name||b.district||b.mapUrl);
  function createContractBatch(f,fd,now){const count=Math.max(1,Math.min(10,Number(fd.get("contractCount"))||1));if(count===1)return false;const sharedSpecs=fd.get("sharedSpecs")==="on",sharedMaintenance=fd.get("sharedMaintenance")==="on",start=fd.get("contractStartDate"),years=Number(fd.get("contractYears")||1),end=dateVal(addYears(new Date(`${start}T00:00`),years)),clientId=cleanId(fd.get("clientId")),num=cleanId(fd.get("clientCompanyUnifiedNumber")),u=users.find(x=>cleanId(x.id)===clientId),cc=clientCompanies.find(x=>cleanId(x.unifiedNumber)===num),own=activeOwnerCompany(),batchId=`CB-${Date.now()}`,common={companyOwnerId:ownerId(),companyId:own?.id||"",type:fd.get("type"),targetType:fd.get("targetType"),clientId,clientName:u?.name||fd.get("clientName")?.trim()||"",clientCompanyUnifiedNumber:num,clientCompanyName:cc?.name||fd.get("clientCompanyName")?.trim()||"",clientPhone:fd.get("clientPhone")?.trim()||"",status:fd.get("contractStatus")==="قديم"?"ساري":fd.get("contractStatus")||"بانتظار موافقة العميل",startDate:start,contractYears:years,endDate:end,createdAt:now,createdAtMs:Date.now(),createdBy:session.id,company:{name:own?.name||"شركة غير محددة"}},baseSpecs=collectBaseContractSpecs(f),baseInst=scopedInstallation({querySelector:s=>baseContractElements(f,s)[0]}),baseMaintenance=collectMaintenanceChecklist({querySelectorAll:s=>baseContractElements(f,s)});const made=[];for(let i=0;i<count;i++){const scope=i===0?f:{querySelector:s=>f.querySelector(`[data-contract-unit="${i+1}"] ${s}`),querySelectorAll:s=>f.querySelectorAll(`[data-contract-unit="${i+1}"] ${s}`)},specs=i===0||sharedSpecs?baseSpecs:collectTechnicalSpecs(scope),inst=i===0||sharedSpecs?baseInst:scopedInstallation(scope),value=i===0?Number(baseContractElements(f,'[name="value"]')[0]?.value||0):Number($('[name="value"]',scope)?.value||0),buildings=i===0?collectBaseContractBuildings(f):collectBuildings(scope),maintenance=i===0||sharedMaintenance?baseMaintenance:collectMaintenanceChecklist(scope),custom=i===0?collectCustom({querySelectorAll:s=>baseContractElements(f,s)}):collectCustom(scope),details=i===0?(baseContractElements(f,'[name="details"]')[0]?.value||""):($('[name="details"]',scope)?.value||""),itemIds=(i===0?baseContractElements(f,'[name="defaultItems"]:checked'):$$( '[name="defaultItems"]:checked',scope)).map(el=>el.value),items=itemIds.map(id=>defaultItems.find(x=>x.id==id)).filter(Boolean);const c={...common,id:nextContractId(),batchId,batchIndex:i+1,batchCount:count,value,elevatorInfo:Object.assign({count:"1",brand:specs.motorManufacturer||"",age:specs.stops||"",capacity:specs.capacity||"",doorType:specs.doorType||"",usage:specs.usage||""},specs),installationInfo:inst,maintenancePeriod:inst.maintenancePeriod||"سنة",maintenanceChecklist:maintenance,buildings,items,customItems:custom,details};contracts.unshift(c);made.push(c)}write("misadContracts",contracts);made.forEach(c=>{if(c.type==="صيانة")generateVisits(c);});made.forEach(c=>logActivity("عقد",`تم إنشاء العقد ${c.batchIndex} من ${c.batchCount}`,c.id));modalClose(`تم حفظ ${made.length} عقود مستقلة`);render("contracts");return true}
  function maintenanceClauses(){return `<section class="contract-section"><h3>سادساً: الضمان على أعمال الصيانة</h3><div class="contract-terms"><article><p>تتحمل الشركة المصنعة أو الموردة أو الشركة المنفذة لأعمال الصيانة (الطرف الأول) مسؤولية ضمان أعمال الصيانة التي تقوم بها وتكون مسؤولة عن أي عيوب أو أخطاء في تلك الأعمال.</p></article><article><p>يكون الضمان ساري المفعول لمدة عام من تاريخ بداية العقد على الأجزاء التي تمت صيانتها أو استبدالها في حالة الصيانة الناتجة عن سوء التركيب أو التصنيع أو عدم سلامة التصنيع.</p></article><article><p>مدة الضمان لعملية الصيانة تكون عاماً من تاريخ التنفيذ، وفي حال وجود أي عيوب في أعمال الصيانة يجب على الطرف الأول إعادة الصيانة أو إصلاح العيوب خلال مدة لا تتجاوز خمسة عشر يوماً من تاريخ الإشعار وبما لا يخل بضمان أعمال الصيانة.</p></article><article><p>في حالة وجود أي عيوب أو أخطاء في الصيانة من وجهة نظر الطرف الثاني، عليه إخطار الطرف الأول بذلك ويجب أن يتضمن الإخطار وصفاً كاملاً للعيوب أو الأخطاء.</p></article></div></section><section class="contract-section"><h3>سابعاً: التزامات الطرف الثاني</h3><div class="contract-terms"><article><p>يلتزم الطرف الثاني بتوفير متطلبات السلامة لحماية العاملين في الموقع، وتوفير مساحة عمل آمنة ومناسبة لفريق الصيانة، مع توفير الإضاءة والطاقة الكهربائية اللازمة لتنفيذ أعمالهم بأمان وسلامة.</p></article><article><p>إخلاء مسؤولية الطرف الأول عن أي حوادث أو إصابات أو أضرار تلحق بالغير أو بالعاملين في الموقع نتيجة إهمال الطرف الثاني أو عدم توفير بيئة عمل آمنة.</p></article><article><p>يلتزم الطرف الثاني بإبلاغ الطرف الأول فوراً في حال حدوث أي عطل مفاجئ في المصعد.</p></article><article><p>في حال عدم قيام الطرف الثاني بالتزاماته، يحق للطرف الأول تعليق الخدمة حتى يتم الالتزام.</p></article></div></section><section class="contract-section"><h3>ثامناً: المسؤولية والسلامة</h3><div class="contract-terms"><article><p>يكون الطرف الأول مسؤولاً عن سلامة تنفيذ أعمال الصيانة وفقاً لأصول المهنة والشروط المتفق عليها.</p></article><article><p>يكون الطرف الثاني مسؤولاً عن سلامة الموقع وتوفير بيئة عمل آمنة وفقاً للوائح وأنظمة السلامة المهنية.</p></article><article><p>يكون الطرف الأول مسؤولاً عن سلامة وأداء المصعد (المصاعد) بعد الصيانة.</p></article></div></section><section class="contract-section"><h3>تاسعاً: التأخير أو التقصير</h3><div class="contract-terms"><article><b>التأخير أو التقصير</b><p>في حال تقصير أو تأخير الطرف الأول في تنفيذ أعمال الصيانة الدورية، يجب عليه إخطار الطرف الثاني بأسباب التأخير.</p></article><article><b>الإخلال بالالتزامات</b><p>في حال إخلال الطرف الأول بالتزاماته الجوهرية، يحق للطرف الثاني تعليق استحقاق الدفعات المستحقة للطرف الأول.</p></article><article><b>حدود المسؤولية</b><p>لا يتحمل الطرف الأول المسؤولية عن الأضرار غير المباشرة (سواء كانت مادية أو معنوية) مثل فقدان الأرباح أو توقف العمل أو غيرها، وتكون المسؤولية في جميع الأحوال محصورة بقيمة العقد المدفوعة من الطرف الثاني للطرف الأول.</p></article><article><b>إيقاف العقد</b><p>يحق للطرف الأول إيقاف العقد في حال عدم قيام الطرف الثاني بدفع الدفعات المستحقة في مواعيدها، على أن يكون الإيقاف بعد إنذار خطي لمدة لا تقل عن 7 أيام.</p></article></div></section><section class="contract-section"><h3>عاشراً: فسخ العقد</h3><div class="contract-terms"><article><p>يحق لأي من الطرفين فسخ العقد في حال إخلال الطرف الآخر بالتزاماته الجوهرية مع إنذار خطي لمدة لا تقل عن 30 يوماً.</p></article><article><p>في حال فسخ العقد، يستحق الطرف الأول قيمة الأعمال التي تم تنفيذها فعلاً.</p></article><article><p>لا يحق للطرف الثاني فسخ العقد بسبب ظروفه المادية أو الإدارية أو تغير موقفه المالي، أو لأي سبب غير مبرر، وإلا أعتبر ذلك إخلالاً بالتزاماته.</p></article></div></section><section class="contract-section"><h3>حادي عشر: المسؤولية عن الأعطال التي تتطلب قطع غيار</h3><div class="contract-terms"><article><b>الأعطال التي تتطلب قطع غيار</b><p>في حال وجود عطل بالمصعد يتطلب تغيير قطعة غيار، تتحمل الطرف الثاني قيمة القطعة وتكاليف الشحن والتركيب والنقل والخدمات اللوجستية، على أن تقوم الطرف الأول بتوفير القطعة وتنفيذ أعمال الاستبدال بأسرع وقت ممكن، ويتم وضع خطة لتفادي توقف المصعد لفترات طويلة.</p></article><article><b>الأعطال غير المشمولة</b><p>أما الأعطال الناتجة عن سوء الاستخدام أو التعديلات غير المصرح بها من قبل الطرف الثاني أو الغير، أو الأعطال الناتجة عن سوء التركيب أو التصنيع من قبل الغير والشركات المنفذة للتركيب أو التصنيع، أو ظروف قاهرة مثل كوارث طبيعية أو حرائق أو فيضانات أو سرقات وتخريب، أو انقطاع التيار الكهربائي أو عدم استقرار الجهد الكهربائي، أو عدم تنفيذ الصيانة الوقائية الدورية المتفق عليها في العقد، أو وجود أي تعديلات هيكلية في المبنى تؤثر على سلامة المصعد، فلا تكون الطرف الأول مسؤولة عنها وتتحمل الطرف الثاني أي تكاليف إضافية لإعادة التأهيل والصيانة.</p></article></div></section><section class="contract-section"><h3>نسخ العقد</h3><div class="contract-terms"><article><p>تم تحرير هذا العقد من نسختين (2) بيد كل طرف نسخة واحدة، وتعتبر جميعها نسخاً أصلية، وتسري أحكام هذا العقد اعتباراً من تاريخ توقيعه من الطرفين.</p></article></div></section>`}
function elevatorSection(i={}){const info=Object.assign({},specDefaults,i||{});return `<section class="contract-section"><h3>المواصفات الفنية للمصعد</h3>${specGroups.map(g=>`<div class="spec-doc-group"><h4>${g.tab}</h4><table class="contract-spec-table"><tbody>${g.fields.map(([k,l])=>`<tr><th>${l}</th><td>${esc(info[k]||"غير محدد")}</td></tr>`).join("")}</tbody></table></div>`).join("")}</section>`}
  function maintenanceElevatorSection(i={}){if(!Object.values(i||{}).some(Boolean))return "";return `<section class="contract-section"><h3>بيانات المصعد</h3><div class="contract-summary">${["count:عدد المصاعد","brand:الماركة","age:العمر","capacity:السعة","doorType:نوع الأبواب","usage:الاستخدام"].map(p=>{const [k,l]=p.split(":");return `<div><small>${l}</small><b>${i[k]||"غير محدد"}</b></div>`}).join("")}</div></section>`}
  function itemPicker(type){const items=defaultItems.filter(i=>i.type===type&&(sameCompany(i)));if(!items.length)return `<div class="form-note">لا توجد بنود افتراضية.</div>`;const secs=[...new Set(items.map(i=>i.section||"بنود عامة"))];return `<fieldset class="item-picker"><legend>البنود الافتراضية</legend>${secs.map(s=>`<div class="item-section"><strong>${s}</strong><label class="item-option select-all" style="font-size:12px;color:#60756f;border-bottom:1px solid #e0e8e4;padding:4px 0;margin-bottom:4px"><input type="checkbox" class="select-all-check" data-section="${esc(s)}"> <span>تحديد الكل</span></label>${items.filter(i=>(i.section||"بنود عامة")===s).map(i=>`<label class="item-option"><input type="checkbox" name="defaultItems" value="${i.id}"><span><b>${i.title}</b><small>${i.description||""} ${i.price?money(i.price):""}</small></span></label>`).join("")}</div>`).join("")}</fieldset>`}
  function customItems(){return `<fieldset class="item-picker"><legend>بنود إضافية</legend><div data-custom-items><div class="custom-item-row"><label>القسم<input name="customItemSection" placeholder="مثال: أعمال إضافية"></label><label>العنوان<input name="customItemTitle"></label><label>الوصف<textarea name="customItemDescription"></textarea></label><label>السعر<input name="customItemPrice" type="number"></label></div></div></fieldset>`}
  // Maintenance checklist items extracted from the approved maintenance reference images.
  const maintenanceSections=[
    {section:"غرفة المصعد",items:["فحص زيت المحرك والتأكد من سيره الطبيعي.","فحص قماش الفرامل.","فحص عمل الفرامل وتضبيطه وتشحيم المحاور.","فحص السيور والتأكد من سلامتها.","فحص سلكتور والطوابق.","فحص جهاز الهبوط الاضطراري.","فحص منظم السرعة وضبطه.","تنظيف أرضية الغرفة.","التأكد من سلامة التمديدات الكهربائية بالغرفة.","التأكد من عدم وجود تهريب مياه بالغرفة.","التأكد من عدم وجود أي تخزين بالغرفة.","التأكد من وجود التكييف بحالة سليمة."]},
    {section:"بئر المصعد",items:["فحص التوصيلات الكهربائية أعلى الصاعدة والتأكد من سلامتها.","فحص جهاز الريفيزيون في حالة الصعود والهبوط والتوقف.","فحص حبال الجر وشدادات الحبال.","فحص بكرات الحبال والتأكد من سلامتها.","تزييت وتشحيم أدلة سير الصاعدة والثقل.","فحص قواطع نهاية المشوار.","فحص مغناطيس الأدوار.","الكشف على مروحة الصاعدة."]},
    {section:"داخل المصعد",items:["الكشف على أزرار التحكم والتشغيل.","الكشف عن الإنارة والجرس والانتركوم.","تنظيف مجاري الأبواب."]},
    {section:"أبواب الطوابق",items:["فحص أبواب الأدوار وضبطها.","فحص محركات الأبواب.","فحص وتنظيف الشوك والكوالين.","فحص مفصلات الأبواب.","فحص الكابلات والمؤشرات والمبينات وضبط الإضاءة."]},
    {section:"حفرة البئر",items:["الكشف على بكرة منظم السرعة.","تنظيف وفحص قواطع نهاية المشوار.","فحص التوصيلات الكهربائية أسفل الصاعدة والتأكد من سلامتها.","تنظيف الحفرة."]}
  ];
  const defaultMaintenanceChecklist=()=>maintenanceSections.flatMap(sec=>sec.items.map((title,i)=>({id:`${sec.section}-${i}`,section:sec.section,title,status:"مطلوب",checked:false,note:""})));
