      const summary=`<div class="form-note"><b>نتيجة فحص القاعدة الحالية:</b> ${Number(current.visible||0)} عقد ظاهر؛ ${Number(current.maintenance||0)} صيانة، ${Number(current.installation||0)} تركيب${Number(current.unclassified||0)?`، ${Number(current.unclassified)} بنوع غير مصنف`:""}${Number(current.hidden||0)?`، ${Number(current.hidden)} مخفي`:""}. تمت مقارنة ${Number(data.checkedSources||0)} نسخة محفوظة.</div>`;
