      const referenceConflicts=(diagnostics.referenceConflicts||[]).filter(item=>Number(item.mismatched||0)>0).slice(0,20);
      const referenceConflictHtml=referenceConflicts.length?`<div class="notice error"><b>تعارض مؤكد بين العقود والسجلات المرتبطة:</b><br>${referenceConflicts.map(item=>`${esc(item.contractId)} (${Number(item.mismatched||0)} سجل مرتبط بطرف مختلف)`).join("، ")}<br><small>هذا يعني أن رقم العقد موجود، لكن بعض الزيارات أو السجلات التابعة له تخص نسخة عقد أخرى.</small></div>`:"";
      const warning=Number(data.unreadableSources||0)?`<div class="notice error">تعذر قراءة ${Number(data.unreadableSources)} نسخة، ولم تُستخدم في النتائج.</div>`:"";
      if(!list.length){host.innerHTML=summary+orphanHtml+referenceConflictHtml+warning+'<div class="notice">لم يعثر الفحص الموسع على نسخة كاملة مختلفة قابلة للاستعادة. لم تُعدّل قاعدة البيانات.</div>';return}
