  const aiFormDraftSave=(type,form)=>{const fd=new FormData(form);const data={};for(const[k,v]of fd.entries())data[k]=v;const isInstall=data.type==="تركيب";const isParts=data.type==="توريد وتركيب قطع غيار";if(isInstall){const elev=collectElevator(form.elements);if(Object.values(elev).some(Boolean))data.elevatorInfo=elev}else if(!isParts){const check=collectMaintenanceChecklist?.(form);if(check?.length)data.maintenanceChecklist=check}const blds=collectBuildings?.(form);if(blds?.length)data.buildings=blds;const inst=collectInstallation?.(form.elements);if(inst&&Object.values(inst).some(Boolean))data.installationInfo=inst;const custom=collectCustom?.(form);if(custom?.length)data.customItems=custom;const drafts=JSON.parse(localStorage.getItem("misadFormDrafts")||"[]");drafts.unshift({id:`DRF-${Date.now()}`,type,data,title:data.title||data.name||data.clientName||data.client||data.buildingName||`مسودة ${type}`,createdAt:new Date().toLocaleString("ar-SA"),updatedAt:new Date().toLocaleString("ar-SA")});const keep=drafts.slice(0,50);localStorage.setItem("misadFormDrafts",JSON.stringify(keep));return keep};
