  function renderTerms(items,emptyText){if(!items?.length)return `<p>${emptyText}</p>`;const secs=[...new Set(items.map(i=>i.section||"بنود عامة"))];return secs.map(s=>`<div class="term-section"><h4>${s}</h4><div class="contract-terms">${items.filter(i=>(i.section||"بنود عامة")===s).map(i=>`<article><b>${i.title||"بند"}</b><p>${i.description||"بدون وصف"}</p>${i.price?`<small>${money(i.price)}</small>`:""}</article>`).join("")}</div></div>`).join("")}
  const defaultPaymentPlan=()=>[{label:"الدفعة الأولى",description:"عند توقيع العقد لتوريد وتركيب السكة والأبواب والبيت الحديدي",percent:50},{label:"الدفعة الثانية",description:"لتوريد وتركيب الكابينة",percent:35},{label:"الدفعة الثالثة",description:"لتوريد وتركيب المكينة ولوحة التحكم والتشغيل والاختبار",percent:15}]
  function installationPayments(value,plan){const total=Number(value||0);const parts=(plan&&plan.length)?plan:defaultPaymentPlan();return parts.map(p=>{if(Array.isArray(p)){return `<tr><td>${p[0]}</td><td>${p[1]}</td><td>${money(total*p[2])}</td></tr>`}const pct=p.percent>1?p.percent/100:p.percent;return `<tr><td>${p.label}</td><td>${p.description}</td><td>${money(total*pct)}</td></tr>`}).join("")}
  function contractPaymentPlanFields(plan,value){const parts=(plan&&plan.length)?plan:defaultPaymentPlan();return `<fieldset class="item-picker" style="margin-top:8px"><legend>خطة الدفعات</legend><div class="form-note">حدد نسب الدفعات. مجموع النسب يجب أن يساوي 100%.</div><table class="payment-plan-table" style="width:100%;border-collapse:collapse;margin-top:8px"><thead><tr style="background:#0d312f;color:#fff;font-size:13px"><th style="padding:8px 10px;text-align:right">الدفعة</th><th style="padding:8px 10px;text-align:right">البيان</th><th style="padding:8px 10px;text-align:center;width:100px">النسبة %</th><th style="padding:8px 10px;text-align:center;width:120px">القيمة المتوقعة</th><th style="padding:8px 10px;text-align:center;width:40px"></th></tr></thead><tbody>${parts.map((p,i)=>{const pct=p.percent||(Array.isArray(p)?(p[2]*100):50);const label=p.label||(Array.isArray(p)?p[0]:'الدفعة '+(i+1));const desc=p.description||(Array.isArray(p)?p[1]:'');return `<tr style="border-bottom:1px solid #dfe8e4"><td><input type="hidden" name="paymentLabel" value="${esc(label)}">${esc(label)}</td><td style="font-size:12px;color:#60756f"><input type="hidden" name="paymentDesc" value="${esc(desc)}">${esc(desc)}</td><td style="text-align:center"><input name="paymentPct" type="number" min="0" max="100" step="0.5" value="${pct}" style="width:80px;text-align:center;padding:6px;border:1px solid #dfe8e4;border-radius:8px;font-family:Cairo,sans-serif;font-weight:700"></td><td style="text-align:center;font-weight:800;color:#17413e" data-payment-amount>${money(Number(value||0)*pct/100)}</td><td style="text-align:center">${parts.length>1?`<button type="button" class="action-btn" data-remove-payment style="color:#c85c59;padding:2px 6px;font-size:12px">✕</button>`:''}</td></tr>`}).join("")}</tbody><tfoot><tr><td colspan="5" style="padding:8px;text-align:center"><span style="font-size:13px;color:#60756f">المجموع: </span><span id="contractPctTotal" style="font-weight:900;font-size:14px">100%</span><span style="margin:0 12px;color:#60756f">|</span><span style="font-size:13px;color:#60756f">الإجمالي: </span><span id="contractPctTotalAmount" style="font-weight:900;font-size:14px">${money(Number(value||0))}</span></td></tr></tfoot></table><button type="button" class="action-btn primary" data-add-payment-installment style="margin-top:8px">+ إضافة دفعة</button></fieldset>`}
  function updateContractPaymentPlan(f){if(!f?.matches?.('[data-form="contract"],[data-form="contract-edit"]'))return;const value=Number(f.value?.value||0);const pcts=$$('[name="paymentPct"]',f);const amounts=$$('[data-payment-amount]',f);let total=0;pcts.forEach((input,i)=>{const pct=Number(input.value||0);total+=pct;if(amounts[i])amounts[i].textContent=money(value*pct/100)});const totalEl=$('#contractPctTotal',f);const totalAmountEl=$('#contractPctTotalAmount',f);if(totalEl)totalEl.textContent=total+'%';if(totalEl)totalEl.style.color=total===100?'#2d7d6d':'#c85c59';if(totalAmountEl)totalAmountEl.textContent=money(value)}
