  function installationContractDetails(c){const fi=contractFinanceInfo(c),company=c.company?.name||activeOwnerCompany()?.name||"شركة غير محددة",client=contractLabel(c),building=(c.buildings||[])[0]||{},install=c.installationInfo||{};return `<style>.installation-contract .contract-section{break-before:auto;page-break-before:auto}.installation-contract .contract-section:nth-of-type(1),.installation-contract .contract-section:nth-of-type(2),.installation-contract .contract-section:nth-of-type(3),.installation-contract .contract-spec-table,.installation-contract .signature-grid section{break-inside:avoid;page-break-inside:avoid}.installation-contract h3{break-after:avoid;page-break-after:avoid}.installation-contract p{orphans:3;widows:3}@media screen{.installation-contract .contract-section{break-before:auto;page-break-before:auto}}</style><div class="contract-document installation-contract"><div class="contract-topline"><span class="contract-type">عرض وعقد توريد وتركيب مصعد</span>${badge(c.status)}</div><div class="contract-number-strip"><span>&#x0631;&#x0642;&#x0645; &#x0627;&#x0644;&#x0639;&#x0642;&#x062f;</span><b>${c.id}</b></div><div class="installation-hero"><div><small>بسم الله الرحمن الرحيم</small><h3>عقد تركيب مصعد فل أوتوماتيك</h3><p>يسعدنا نحن ${company} أن نتقدم لسعادتكم بهذا العقد لتوريد وتركيب مصعد في موقعكم الموضح أدناه، وفق المواصفات الفنية والبنود العامة المعتمدة.</p></div><strong>${money(c.value)}</strong></div><div class="contract-summary"><div><small>السيد / الطرف الثاني</small><b>${client}</b></div><div><small>الموقع</small><b>${building.name||"غير محدد"} ${building.district||""}</b></div><div><small>تاريخ العقد</small><b>${c.startDate||"غير محدد"}</b></div><div><small>الإجمالي</small><b>${money(c.value)}</b></div><div><small>منشأة الإصدار</small><b>${company}</b></div><div><small>مدة التركيب</small><b>${install.installDuration||"45 يوماً"}</b></div>${c.deliveryDate?`<div><small>تاريخ التسليم</small><b>${c.deliveryDate}</b></div>`:""}${c.paymentMethod?`<div><small>طريقة الدفع</small><b>${esc(c.paymentMethod)}</b></div>`:""}</div>${(function(){let h='';const notices=(c.transferNotices||[]).slice();if(c.transferNoticeData)notices.unshift({data:c.transferNoticeData,name:c.transferNoticeName||'إشعار تحويل'});const imgs=notices.filter(n=>n.data&&n.data.startsWith('data:image/'));if(imgs.length){h+=imgs.map(n=>`<img src="${n.data}" style="max-width:100%;max-height:200px;border-radius:6px;margin-top:8px;display:block">`).join('')}if(c.financialNotes){h+=`<section class="contract-section"><h3>ملاحظات مالية</h3><p>${esc(c.financialNotes)}</p></section>`}return h})()}<section class="contract-section"><h3>البند الأول: نطاق التوريد والتركيب</h3><p>${c.details||"يشمل العقد توريد وتركيب المصعد والسكة والأبواب والكابينة والمكينة ولوحة التحكم والتشغيل والاختبار وفق المواصفات الفنية المعتمدة، وتشمل القيمة جميع الرسوم ما لم يذكر خلاف ذلك."}${install.note?`<br>${esc(install.note)}`:""}</p></section><section class="contract-section"><h3>البند الثاني: الدفعات</h3><table class="contract-spec-table"><thead><tr><th>الدفعة</th><th>البيان</th><th>القيمة</th></tr></thead><tbody>${installationPayments(c.value,c.paymentPlan)}</tbody></table></section><section class="contract-section"><h3>الإدارة المالية للعقد</h3><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px"><div style="background:#f8fbf9;padding:10px;border-radius:8px;text-align:center"><small style="display:block;color:#6b7f7a;font-size:11px">إجمالي العقد</small><b style="font-size:15px;color:#0d312f">${money(c.value)}</b></div><div style="background:#f8fbf9;padding:10px;border-radius:8px;text-align:center"><small style="display:block;color:#6b7f7a;font-size:11px">إجمالي المدفوع</small><b style="font-size:15px;color:#3c8b70">${money(fi.paid)}</b></div><div style="background:#f8fbf9;padding:10px;border-radius:8px;text-align:center"><small style="display:block;color:#6b7f7a;font-size:11px">المبلغ المتبقي</small><b style="font-size:15px;color:${fi.remaining>0?'#c85c59':'#3c8b70'}">${money(fi.remaining)}</b></div><div style="background:#f8fbf9;padding:10px;border-radius:8px;text-align:center"><small style="display:block;color:#6b7f7a;font-size:11px">المبالغ المتأخرة</small><b style="font-size:15px;color:${fi.overdue>0?'#c85c59':'#3c8b70'}">${money(fi.overdue)}</b></div></div></section><section class="contract-section"><h3>البند الثالث: المواصفات الفنية</h3><table class="contract-spec-table"><tbody>${installationSpecRows(c)}</tbody></table></section><section class="contract-section"><h3>البند الرابع: المباني والمواقع</h3>${renderTerms((c.buildings||[]).map(b=>({section:"مواقع العقد",title:b.name,description:`${b.district||""} ${b.mapUrl||""}`})),"لا توجد مواقع.")}</section><section class="contract-section"><h3>البند الخامس: الأحكام العامة</h3><div class="contract-terms"><article><b>المرفقات</b><p>تعتبر أي مرفقات أو مواصفات أو رسومات موقعة من الطرفين جزءا لا يتجزأ من هذا العقد.</p></article><article><b>التأخير والتعديلات</b><p>أي تأخير في الأعمال التحضيرية أو الدفعات أو تعديل المناسيب وفتحات الأبواب قد يترتب عليه تمديد مدة التسليم وتحميل الطرف الثاني أي تكاليف إضافية لازمة.</p></article><article><b>نقل الملكية</b><p>لا يحق للطرف الثاني بيع أو نقل أو التنازل عن المصعد قبل سداد قيمة العقد كاملة، وعند انتقال ملكية العقار يتم تزويد الطرف الأول ببيانات المالك الجديد.</p></article><article><b>الخلافات</b><p>تسوى الخلافات وديا، وفي حال تعذر ذلك يكون الاختصاص للجهة القضائية المختصة في موقع المشروع.</p></article></div></section><section class="contract-section"><h3>البند السادس: التوريد والتركيب والضمان</h3><div class="contract-terms"><article><b>التزام الطرف الأول</b><p>يلتزم الطرف الأول بتوريد وتركيب المصعد حسب أصول الصنعة ومتطلبات السلامة المعمول بها في المملكة العربية السعودية.</p></article><article><b>إيقاف الأعمال</b><p>يحق للطرف الأول إيقاف أعمال التوريد أو التركيب عند عدم سداد الدفعات المستحقة أو عدم جاهزية الأعمال التحضيرية.</p></article><article><b>الضمان والصيانة</b><p>يبدأ الضمان من تاريخ تشغيل المصعد ولمدة سنة، ولا يشمل سوء الاستخدام. تبدأ الصيانة بعد سداد قيمة العقد كاملة واستلام المصعد.</p></article></div></section><section class="contract-section"><h3>البند السابع: الأعمال التحضيرية على الطرف الثاني</h3><div class="contract-terms"><article><b>بيت المصعد وغرفة المحرك</b><p>تجهيز بيت المصعد وغرفة المحرك والعزل والإنارة والتهوية وفتحات الأبواب حسب الأبعاد المعتمدة قبل بدء الأعمال.</p></article><article><b>التيار الكهربائي والمستودع</b><p>تأمين التيار الكهربائي المناسب ومكان آمن لحفظ أجزاء المصعد طوال فترة التركيب.</p></article><article><b>السقالة والتدريب</b><p>تأمين السقالة عند الحاجة، وتعيين من يراه الطرف الثاني مناسبا لتدريبه على إنزال الكابينة يدويا في حالات الطوارئ.</p></article></div></section><section class="contract-section"><h3>البنود الإضافية</h3>${renderTerms([...(c.items||[]),...(c.customItems||[])],"لا توجد بنود إضافية.")}</section><section class="contract-section"><h3>الصيانة بعد التسليم</h3><p>يتضمن هذا العقد عقد صيانة للمصعد يبدأ سريانه تلقائياً من تاريخ تسليم المصعد للطرف الثاني، وتصدر بنود الصيانة وشروطها في عقد الصيانة المرتبط بهذا العقد، ويمكن تنزيله أو طباعته من نظام إدارة الشركة.</p></section><section class="contract-section"><h3>نسخ العقد</h3><p>حرر هذا العقد من نسختين أصليتين بيد كل طرف نسخة للعمل بموجبها.</p></section>${signatureArea(c,c.companyOwnerId)}</div>`}
  function installReceiptDetails(c){const company=c.company?.name||activeOwnerCompany()?.name||"شركة غير محددة",client=contractLabel(c),building=(c.buildings||[])[0]||{};return `<div class="contract-document installation-contract"><div class="contract-topline"><span class="contract-type">إقرار استلام مصعد</span>${badge(c.status)}</div><div class="contract-number-strip"><span>رقم العقد</span><b>${c.id}</b></div><div class="installation-hero"><div><small>بسم الله الرحمن الرحيم</small><h3>إقرار استلام مصعد</h3><p>أنا الموقع أدناه / الطرف الثاني في عقد التركيب رقم (${c.id}) أقر بأنني استلمت المصعد المذكور في العقد بتاريخ (${c.deliveryDate||"—"}) بعد إتمام تركيبه واختباره وتشغيله والتأكد من سلامته وكفاءته وفق المواصفات الفنية والبنود الواردة في العقد، وأقر بأنه مطابق لما تم الاتفاق عليه وتم التسليم بحالة جيدة وتامة.</p></div></div><div class="contract-summary"><div><small>الطرف الثاني</small><b>${client}</b></div><div><small>الموقع</small><b>${building.name||"غير محدد"} ${building.district||""}</b></div><div><small>تاريخ التسليم</small><b>${c.deliveryDate||"—"}</b></div>${c.maintenanceEndDate?`<div><small>نهاية فترة الصيانة</small><b>${c.maintenanceEndDate}</b></div>`:""}<div><small>منشأة الإصدار</small><b>${company}</b></div></div><section class="contract-section"><h3>الصيانة بعد التسليم</h3><p>يبدأ عقد الصيانة المرتبط بهذا العقد سريانه تلقائياً من تاريخ تسليم المصعد الموضح أعلاه، وتصدر بنود الصيانة وشروطها في عقد الصيانة المرتبط، ويمكن الحصول على نسخة منه من الشركة.</p></section>${signatureArea(c,c.companyOwnerId)}</div>`}
  function contractDetails(c){if(c.type==="\u062a\u0631\u0643\u064a\u0628")return installationContractDetails(c);return `<div class="contract-document"><div class="contract-topline"><span class="contract-type">&#x0639;&#x0642;&#x062f; ${c.type}</span>${badge(c.status)}</div><div class="contract-number-strip"><span>&#x0631;&#x0642;&#x0645; &#x0627;&#x0644;&#x0639;&#x0642;&#x062f;</span><b>${c.id}</b></div><section class="contract-section party-section"><h3>&#x0627;&#x0644;&#x0637;&#x0631;&#x0641; &#x0627;&#x0644;&#x062b;&#x0627;&#x0646;&#x064a;</h3><p class="pdf-party-name">${contractLabel(c)}</p></section><div class="contract-title"><div><span>&#x0642;&#x064a;&#x0645;&#x0629; &#x0627;&#x0644;&#x0639;&#x0642;&#x062f;</span><b>${money(c.value)}</b></div></div><div class="contract-summary"><div><small>&#x0628;&#x062f;&#x0627;&#x064a;&#x0629; &#x0627;&#x0644;&#x0639;&#x0642;&#x062f;</small><b>${c.startDate||"&#x063a;&#x064a;&#x0631; &#x0645;&#x062d;&#x062f;&#x062f;"}</b></div><div><small>&#x0646;&#x0647;&#x0627;&#x064a;&#x0629; &#x0627;&#x0644;&#x0639;&#x0642;&#x062f;</small><b>${c.endDate||"&#x063a;&#x064a;&#x0631; &#x0645;&#x062d;&#x062f;&#x062f;"}</b></div><div><small>&#x0645;&#x0646;&#x0634;&#x0623;&#x0629; &#x0627;&#x0644;&#x0625;&#x0635;&#x062f;&#x0627;&#x0631;</small><b>${c.company?.name||activeOwnerCompany()?.name||"&#x063a;&#x064a;&#x0631; &#x0645;&#x062d;&#x062f;&#x062f;"}</b></div></div>${c.paymentMethod?`<div><small>&#x637;&#x631;&#x64a;&#x642;&#x629; &#x627;&#x644;&#x62f;&#x641;&#x639;</small><b>${esc(c.paymentMethod)}</b></div>`:''}</div>${(function(){let h='';const notices=(c.transferNotices||[]).slice();if(c.transferNoticeData)notices.unshift({data:c.transferNoticeData,name:c.transferNoticeName||'&#x625;&#x634;&#x639;&#x627;&#x631; &#x62a;&#x62d;&#x648;&#x64a;&#x644;'});const imgs=notices.filter(function(n){return n.data&&n.data.indexOf('data:image/')===0});if(imgs.length){h+=imgs.map(function(n){return '<img src="'+n.data+'" style="max-width:100%;max-height:200px;border-radius:6px;margin-top:8px;display:block">'}).join('')}if(c.financialNotes){h+='<section class="contract-section"><h3>&#x645;&#x644;&#x627;&#x62d;&#x638;&#x627;&#x62a; &#x645;&#x627;&#x644;&#x64a;&#x629;</h3><p>'+esc(c.financialNotes)+'</p></section>'}return h})()}${elevatorSection(c.elevatorInfo)}<section class="contract-section"><h3>&#x0628;&#x0646;&#x648;&#x62f; &#x0627;&#x644;&#x635;&#x64a;&#x627;&#x646;&#x629; &#x0627;&#x644;&#x62f;&#x648;&#x631;&#x64a;&#x629;</h3>${renderMaintenanceChecklist(c.maintenanceChecklist)}</section><section class="contract-section"><h3>&#x639;&#x62f;&#x62f; &#x627;&#x644;&#x632;&#x64a;&#x627;&#x631;&#x627;&#x62a;</h3><p>&#x639;&#x62f;&#x62f; &#x627;&#x644;&#x632;&#x64a;&#x627;&#x631;&#x627;&#x62a; &#x627;&#x62b;&#x646;&#x62a;&#x627; &#x639;&#x634;&#x631;&#x629; 12 &#x632;&#x64a;&#x627;&#x631;&#x629;</p></section><section class="contract-section"><h3>&#x0627;&#x0644;&#x0645;&#x0628;&#x0627;&#x0646;&#x064a; &#x0648;&#x0627;&#x0644;&#x0645;&#x0648;&#x0627;&#x0642;&#x0639;</h3>${renderTerms((c.buildings||[]).map(b=>({section:"&#x0645;&#x0648;&#x0627;&#x0642;&#x0639; &#x0627;&#x0644;&#x0639;&#x0642;&#x062f;",title:b.name,description:`${b.district||""} ${b.mapUrl||""}`})) ,"&#x0644;&#x0627; &#x062a;&#x0648;&#x062c;&#x062f; &#x0645;&#x0648;&#x0627;&#x0642;&#x0639;.")}</section><section class="contract-section"><h3>&#x0627;&#x0644;&#x0628;&#x0646;&#x0648;&#x062f; &#x0627;&#x0644;&#x0627;&#x0641;&#x062a;&#x0631;&#x0627;&#x0636;&#x064a;&#x0629;</h3>${renderTerms(c.items,"&#x0644;&#x0627; &#x062a;&#x0648;&#x062c;&#x062f; &#x0628;&#x0646;&#x0648;&#x062f; &#x0627;&#x0641;&#x062a;&#x0631;&#x0627;&#x0636;&#x064a;&#x0629;.")}</section><section class="contract-section"><h3>&#x0627;&#x0644;&#x0628;&#x0646;&#x0648;&#x062f; &#x0627;&#x0644;&#x0625;&#x0636;&#x0627;&#x0641;&#x064a;&#x0629;</h3>${renderTerms(c.customItems,"&#x0644;&#x0627; &#x062a;&#x0648;&#x062c;&#x062f; &#x0628;&#x0646;&#x0648;&#x062f; &#x0625;&#x0636;&#x0627;&#x0641;&#x064a;&#x0629;.")}</section><section class="contract-section"><h3>&#x0646;&#x0637;&#x0627;&#x0642; &#x0627;&#x0644;&#x0639;&#x0645;&#x0644;</h3><p>${c.details||"&#x0644;&#x0627; &#x062a;&#x0648;&#x062c;&#x062f; &#x062a;&#x0641;&#x0627;&#x0635;&#x064a;&#x0644; &#x0625;&#x0636;&#x0627;&#x0641;&#x064a;&#x0629;."}</p></section>${maintenanceClauses()}${signatureArea(c,c.companyOwnerId)}</div>`}

  function ticketDetails(t){const loc=t.assignedTo?locations.find(l=>cleanId(l.identity)===cleanId(t.assignedTo)&&l.live):null;return `<div class="report-details"><dl><dt>العميل / المنشأة</dt><dd>${t.clientCompanyName||t.clientName||"غير محدد"}</dd><dt>رقم البلاغ</dt><dd>${t.id}</dd><dt>العنوان</dt><dd>${t.title}</dd><dt>الوصف</dt><dd>${t.description}</dd><dt>العقد</dt><dd>${t.contractId||"غير مرتبط"}</dd><dt>الموقع</dt><dd>${t.building?.name||"غير محدد"} ${t.building?.district||""}</dd><dt>الحالة</dt><dd>${t.status}</dd><dt>المسند إليه</dt><dd>${staff.find(s=>s.identity===t.assignedTo)?.name||t.assignedTo||"غير مسند"}</dd><dt>موقع الفني القادم</dt><dd>${loc?mapLink(loc.mapUrl,"عرض الموقع المباشر"):"غير متاح حاليًا"}</dd></dl></div>${elevatorSection(t.elevatorInfo)}${signatureArea(t)}`}
  function visitReport(v){return reports.find(r=>r.visitId===v.id)}
  function canWriteReport(v){return ["technician","engineer"].includes(session.role)&&cleanId(v.assignedTo)===cleanId(session.id)&&!visitReport(v)}
  function visitRoom(v){return `shumoos-${String(v.id||"visit").replace(/[^a-zA-Z0-9-]/g,"")}`}
  function visitCommunication(v){const c=contracts.find(x=>x.id===v.contractId)||{},tech=staff.find(s=>cleanId(s.identity)===cleanId(v.assignedTo))||{},msgs=visitMessages.filter(m=>m.visitId===v.id).slice(-50),room=visitRoom(v),meet=`https://meet.jit.si/${room}`,phone=tech.phone||tech.mobile||v.building?.guardMobile||c.buildings?.[0]?.guardMobile||"";return `<div class="visit-comms"><div class="quick-grid"><a class="quick-card" target="_blank" rel="noopener" href="${meet}"><b>مكالمة فيديو</b><small>غرفة الزيارة ${v.id}</small></a><a class="quick-card" target="_blank" rel="noopener" href="${phone?`tel:${phone}`:meet}"><b>مكالمة صوتية</b><small>${phone||"عبر غرفة الاجتماع"}</small></a><button class="quick-card" type="button" data-copy-invite="${meet}"><b>نسخ رابط الاجتماع</b><small>للمشاركة مع الطرف الآخر</small></button></div><section class="panel"><h3>رسائل الزيارة</h3><div class="visit-chat">${msgs.length?msgs.map(m=>`<article><b>${esc(m.senderName)}</b><small>${esc(m.createdAt)}</small><p>${esc(m.text)}</p></article>`).join(""):"لا توجد رسائل بعد."}</div><form class="modal-form" data-form="visit-message"><input type="hidden" name="visitId" value="${esc(v.id)}"><label>رسالة جديدة<textarea name="message" required placeholder="اكتب رسالة مرتبطة بهذه الزيارة"></textarea></label><button class="btn-primary">إرسال الرسالة</button></form></section></div>`}
  function visitActions(v){const r=visitReport(v);let b=`<button class="action-btn primary" data-visit-comms="${v.id}">تواصل</button>`;if(r)b+=` <button class="action-btn primary" data-view-report="${r.id}">عرض التقرير</button>`;if(canWriteReport(v))b+=` <button class="action-btn primary" data-action="visit-report:${v.id}">تعبئة التقرير</button>`;if(v.status==="بانتظار الاعتماد"&&session.role==="client"&&matchClient(v))b+=` <button class="action-btn success" data-approve-visit="${v.id}">اعتماد الزيارة</button>`;if(v.status==="بانتظار الاعتماد"&&["technician","engineer"].includes(session.role)&&cleanId(v.assignedTo)===cleanId(session.id))b+=` <button class="action-btn" data-enter-code="${v.id}">إدخال رمز العميل</button>`;if(v.status==="بانتظار التقييم"&&session.role==="client"&&matchClient(v))b+=` <button class="action-btn primary" data-rate-visit="${v.id}">تقييم الفني</button>`;if(v.rating)b+=` <span class="badge success">${"★".repeat(v.rating.stars)}${"☆".repeat(5-v.rating.stars)}</span>`;return b}
  function meetingUrl(m){return m.url||`https://meet.jit.si/${m.room}`}
  function meetingInvitees(m){return (m.invitees||[]).map(id=>staff.find(s=>cleanId(s.identity)===cleanId(id))?.name||users.find(u=>cleanId(u.id)===cleanId(id))?.name||id).join("، ")||"كل الفريق"}
  function meetingsPage(){const rows=meetings.filter(m=>sameCompany(m)||m.createdBy===session.id).map(m=>[m.title,fmtDate(m.scheduledAt),meetingInvitees(m),m.createdByName||"—",`<a class="action-btn primary" target="_blank" rel="noopener" href="${meetingUrl(m)}">دخول</a> <button class="action-btn" data-copy-invite="${meetingUrl(m)}">نسخ</button> <button class="action-btn" data-share-invite="${meetingUrl(m)}" data-share-label="${esc(m.title)}">مشاركة</button>`]);return head("الاجتماعات","إنشاء اجتماعات ودعوة أعضاء الفريق",["owner","company_admin","admin"].includes(session.role)?'<button class="btn-primary" data-action="meeting">اجتماع جديد</button>':"")+(rows.length?table(["العنوان","الموعد","المدعوون","المنشئ","الإجراء"],rows):empty("لا توجد اجتماعات","أنشئ اجتماعًا جديدًا وشارك رابطه مع الأعضاء."))}
  function meetingForm(){const members=[...staff.filter(s=>sameCompany(s)),...users.filter(u=>["owner","company_admin","technician"].includes(u.role))],opts=members.map(m=>`<label class="check"><input type="checkbox" name="invitees" value="${esc(m.identity||m.id)}"> ${esc(m.name)} - ${roles[m.role]||m.role}</label>`).join("")||"<p>لا يوجد أعضاء متاحون.</p>";return `<form class="modal-form" data-form="meeting"><label>عنوان الاجتماع<input name="title" required placeholder="مثال: تنسيق زيارة عاجلة"></label><label>الموعد<input name="scheduledAt" type="datetime-local" required></label><label>ملاحظات<textarea name="notes" placeholder="موضوع الاجتماع أو تعليمات مختصرة"></textarea></label><fieldset class="item-picker"><legend>دعوة الأعضاء</legend>${opts}</fieldset><button class="btn-primary">إنشاء الاجتماع</button>${aiDraftBtn("meeting")}</form>`}
  function reportDetails(r){const v=visits.find(x=>x.id===r.visitId)||{},c=contracts.find(x=>x.id===r.contractId)||{};const quoteBtn=["owner","company_admin","admin"].includes(session.role)?`<div class="contract-actions"><button class="btn-primary" data-action="quote-from-report:${r.id}">إنشاء عرض سعر من التقرير</button></div>`:"";return `<div class="contract-document visit-report-doc"><div class="contract-topline"><span class="contract-type">تقرير زيارة فنية</span>${badge(r.status||"بانتظار اعتماد العميل")}</div><div class="contract-title"><div><span>رقم التقرير</span><b>${r.id}</b></div><strong>${r.technician||r.technicianId||"الفني"}</strong></div><div class="contract-summary"><div><small>العقد</small><b>${r.contractId||"زيارة كشفية"}</b></div><div><small>الطرف الثاني</small><b>${partyLabel(r)}</b></div><div><small>الموقع</small><b>${v.building?.name||r.buildingName||"غير محدد"}</b></div><div><small>موعد الزيارة</small><b>${fmtDate(v.scheduledAt)}</b></div><div><small>تاريخ التقرير</small><b>${r.createdAt||"غير محدد"}</b></div><div><small>حالة المصعد</small><b>${r.elevatorStatus||"غير محدد"}</b></div></div><section class="contract-section"><h3>الأعمال المنفذة</h3><p>${r.workDone||"لا توجد تفاصيل."}</p></section><section class="contract-section"><h3>الأعطال والملاحظات الفنية</h3><p>${r.issues||"لا توجد ملاحظات."}</p></section><section class="contract-section"><h3>قطع الغيار المطلوبة / المستخدمة والتوصيات</h3><p>${r.parts||"لا توجد قطع مسجلة."}</p><p>${r.recommendations||"لا توجد توصيات."}</p></section><section class="contract-section"><h3>صور أو روابط مرفقة</h3><p>${r.attachments||"لا توجد مرفقات."}</p></section>${signatureArea(r)}<div class="form-note decision-note">هذا التقرير محفوظ للعرض فقط ولا يمكن تعديله بعد إرساله.</div>${quoteBtn}</div>`}
  function reportForm(v){const c=contracts.find(x=>x.id===v.contractId)||{};return `<form class="modal-form visit-report-form" data-form="visit-report"><input type="hidden" name="visitId" value="${esc(v.id)}"><div class="form-note">سيتم حفظ التقرير نهائيًا بعد الإرسال، ولن يمكن تعديله لاحقًا.</div><fieldset class="item-picker"><legend>بيانات الزيارة</legend><div class="report-details"><dl><dt>الزيارة</dt><dd>${v.id}</dd><dt>العقد</dt><dd>${v.contractId||"زيارة كشفية قبل العقد"}</dd><dt>الطرف الثاني</dt><dd>${partyLabel(v)}</dd><dt>الموقع</dt><dd>${v.building?.name||"غير محدد"} ${v.building?.district||""}</dd><dt>الموعد</dt><dd>${fmtDate(v.scheduledAt)}</dd></dl></div></fieldset><label>حالة المصعد بعد الزيارة<select name="elevatorStatus" required><option>يعمل بشكل طبيعي</option><option>يعمل مع ملاحظات</option><option>متوقف عن العمل</option><option>يحتاج زيارة إضافية</option></select></label><label>الأعمال المنفذة<textarea name="workDone" required placeholder="اكتب ما تم تنفيذه أثناء الزيارة"></textarea></label><label>الأعطال أو الملاحظات الفنية<textarea name="issues" placeholder="اكتب الأعطال أو الملاحظات إن وجدت"></textarea></label><label>القطع المستخدمة أو المطلوبة<textarea name="parts" placeholder="مثال: حساس باب، زيت، لوحة تحكم..."></textarea></label><label>التوصيات<textarea name="recommendations" placeholder="توصيات الصيانة أو السلامة"></textarea></label><label>روابط صور أو مرفقات<textarea name="attachments" placeholder="يمكن لصق روابط صور أو ملفات هنا"></textarea></label><button class="btn-primary">إرسال التقرير النهائي</button></form>`}
  function scoutingVisitForm(){return `<form class="modal-form" data-form="scouting-visit">${aiAssistantHTML("visit")}<fieldset class="item-picker"><legend>بيانات العميل والمنشأة</legend><label>هوية العميل<input name="clientId" data-client-id></label><label>اسم العميل<input name="clientName"></label><label>الرقم الموحد للمنشأة<input name="clientCompanyUnifiedNumber" data-company-number></label><label>اسم المنشأة<input name="clientCompanyName"></label><div data-client-preview class="client-preview">أدخل الهوية أو الرقم الموحد لجلب البيانات المسجلة.</div></fieldset><fieldset class="item-picker"><legend>موقع الكشف</legend><label>اسم المبنى<input name="buildingName" required></label><label>الحي<input name="buildingDistrict" required></label><label>رابط الخريطة<input name="buildingMapUrl" type="url"></label><label>جوال المسؤول<input name="buildingGuardMobile"></label></fieldset>${elevatorFields()}<label>موعد الزيارة الكشفية<input name="scheduledAt" type="datetime-local" required></label><label>ملاحظات أولية<textarea name="notes"></textarea></label><button class="btn-primary">إنشاء وإسناد تلقائي</button>${aiDraftBtn("visit")}</form>`}
  function updateQuoteTypeFields(f){if(!f?.matches?.('[data-form="quote"]'))return;const v=f.type?.value||"";const isInstall=v==="تركيب";const isParts=v==="توريد وتركيب قطع غيار";const installFields=f.querySelector(".quote-install-fields");if(installFields)installFields.style.display=isInstall?"":"none";const maintenanceSection=f.querySelector(".quote-maintenance-fields");if(maintenanceSection)maintenanceSection.style.display=(isInstall||isParts)?"none":""}
  function quotePaymentPlanFields(plan){const parts=(plan&&plan.length)?plan:defaultPaymentPlan();return `<fieldset class="item-picker"><legend>جدول الدفعات</legend><div class="form-note">حدد نسب الدفعات بناءً على المبلغ الإجمالي أعلاه. سيتم تحديث القيم تلقائياً عند تغيير المبلغ.</div><table class="payment-plan-table" style="width:100%;border-collapse:collapse;margin-top:8px"><thead><tr style="background:#0d312f;color:#fff;font-size:13px"><th style="padding:8px 10px;text-align:right">الدفعة</th><th style="padding:8px 10px;text-align:right">البيان</th><th style="padding:8px 10px;text-align:center;width:80px">النسبة %</th><th style="padding:8px 10px;text-align:center;width:100px">القيمة</th></tr></thead><tbody>${parts.map((p,i)=>{const pct=p.percent||(Array.isArray(p)?p[2]*100:50);const label=p.label||(Array.isArray(p)?p[0]:`الدفعة ${i+1}`);const desc=p.description||(Array.isArray(p)?p[1]:"");return `<tr style="border-bottom:1px solid #dfe8e4"><td><input type="hidden" name="paymentLabel" value="${esc(label)}">${esc(label)}</td><td><input type="hidden" name="paymentDesc" value="${esc(desc)}">${esc(desc)}</td><td style="text-align:center"><input name="paymentPct" type="number" min="0" max="100" step="0.5" value="${pct}" style="width:70px;text-align:center;padding:6px;border:1px solid #dfe8e4;border-radius:8px;font-family:Cairo,sans-serif;font-weight:700"></td><td style="text-align:center;font-weight:800;color:#17413e" data-payment-amount>${money(0)}</td></tr>`}).join("")}</tbody></table></fieldset>`}
  function updateQuotePaymentPlan(f){if(!f?.matches?.('[data-form="quote"]'))return;const value=Number(f.value?.value||0);const pcts=$$('[name="paymentPct"]',f);const amounts=$$('[data-payment-amount]',f);pcts.forEach((input,i)=>{if(amounts[i])amounts[i].textContent=money(value*Number(input.value||0)/100)})}
  function quoteForm(r=null){const detail=r?`قطع الغيار المطلوبة: ${r.parts||"غير محدد"}\nالتوصيات: ${r.recommendations||"غير محدد"}\nمرجع التقرير: ${r.id}`:"";return `<form class="modal-form" data-form="quote">${r?`<input type="hidden" name="reportId" value="${esc(r.id)}">`:""}${aiAssistantHTML("quote")}<fieldset class="item-picker"><legend>بيانات العميل والمنشأة</legend><label>هوية العميل<input name="clientId" data-client-id value="${esc(r?.clientId)}"></label><label>اسم العميل<input name="clientName" value="${esc(r?.clientName)}"></label><label>الرقم الموحد للمنشأة<input name="clientCompanyUnifiedNumber" data-company-number value="${esc(r?.clientCompanyUnifiedNumber)}"></label><label>اسم المنشأة<input name="clientCompanyName" value="${esc(r?.clientCompanyName)}"></label><label>العميل الظاهر في العرض<input name="client" value="${esc(r?.clientCompanyName||r?.clientName)}" required></label><div data-client-preview class="client-preview">أدخل الهوية أو الرقم الموحد لجلب البيانات المسجلة.</div></fieldset><label>العنوان<input name="title" required value="${r?"عرض سعر بناء على تقرير كشف":""}"></label><label>نوع عرض السعر<select name="type"><option>تركيب</option><option>صيانة</option><option>توريد وتركيب قطع غيار</option></select></label><div class="quote-install-fields">${elevatorFields()}${quotePaymentPlanFields(r?.paymentPlan)}</div><div class="quote-maintenance-fields">${maintenanceChecklistFields()}</div>${itemPicker("quote")}${quotePartsPicker()}${customItems()}<label>القيمة الأساسية<input name="value" type="number" min="0" step="0.01" value="0" required></label>${quoteTotalsBox()}<label>التفاصيل<textarea name="details">${esc(detail)}</textarea></label><button class="btn-primary">حفظ وتوجيه العرض للعميل</button>${aiDraftBtn("quote")}</form>`}
  const fullContractForm=contractForm;
  // عقد الصيانة فقط يستخدم ثلاثة تبويبات؛ عقد التركيب يحتفظ بتبويبات المواصفات كاملة.
  function syncContractTabLayout(form,isInstall){
    if(!form)return;
    const tabBar=Array.from(form.children).find(x=>x.classList?.contains("contract-tabs"));
    const panels=Array.from(form.children).filter(x=>x.hasAttribute?.("data-contract-tab-panel"));
    if(!tabBar||panels.length<3)return;
    panels.forEach((panel,index)=>{if(panel.dataset.contractOriginalTabPanel===undefined)panel.dataset.contractOriginalTabPanel=String(index)});
    const mode=isInstall?"installation":"maintenance";
    if(form.dataset.contractTabsMode===mode)return;
    const lastIndex=panels.length-1,activePanel=panels.find(panel=>panel.classList.contains("active"))||panels[0];
    const activeOriginal=Number(activePanel.dataset.contractOriginalTabPanel||0);
    const activeTab=isInstall?(activeOriginal===lastIndex?0:activeOriginal):(activeOriginal===0?0:(activeOriginal===lastIndex?2:1));
    const labels=isInstall?["البيانات الأساسية",...specGroups.map(group=>group.tab),"الصيانة"]:["البيانات الأساسية","مواصفات المصعد","الصيانة"];
    tabBar.innerHTML=labels.map((label,index)=>'<button type="button" class="contract-tab '+(index===activeTab?"active":"")+'" data-contract-tab="'+index+'">'+label+'</button>').join("");
    panels.forEach(panel=>{
      const original=Number(panel.dataset.contractOriginalTabPanel||0);
      const tabIndex=isInstall?original:(original===0?0:(original===lastIndex?2:1));
      panel.dataset.contractTabPanel=String(tabIndex);
      panel.classList.toggle("active",tabIndex===activeTab);
      panel.style.display="";
    });
    form.dataset.contractTabsMode=mode;
  }
  function threeTabContractForm(c=null){
    const template=document.createElement("template");
    template.innerHTML=fullContractForm(c).trim();
    const form=template.content.querySelector("form");
    if(!form)return fullContractForm(c);
    form.querySelector('[name="paymentMethod"]')?.closest("label")?.remove();
    form.querySelector('[name="transferNotice"]')?.closest("label")?.remove();
    form.querySelector('[name="contractTransferNotice"]')?.closest("fieldset")?.remove();
    syncContractTabLayout(form,c?.type==="تركيب");
    return form.outerHTML;
  }
  contractForm=threeTabContractForm;

  const updateContractTypeFieldsBase=updateContractTypeFields;
  updateContractTypeFields=function(f){
    updateContractTypeFieldsBase(f);
    const isInstall=f?.type?.value==="تركيب";
    const isParts=f?.type?.value==="توريد وتركيب قطع غيار";
    const panels=Array.from(f?.children||[]).filter(x=>x.hasAttribute?.("data-contract-tab-panel"));
    const lastPanel=panels[panels.length-1];
    if(lastPanel&&!lastPanel.querySelector(".parts-contract-mode")){
      const id=f.querySelector('[name="contractId"]')?.value||"",contract=contracts.find(x=>x.id===id);
      const savedParts=contract?.partsItems?.length?contract.partsItems:(contract?.customItems||[]).filter(x=>x.section==="قطع الغيار");
      lastPanel.insertAdjacentHTML("afterbegin",`<div class="parts-contract-mode" style="display:none"><div class="form-note">حدد قطع الغيار والكميات. تُجلب أسعار الموردين المسجلة تلقائياً ويمكن توضيح نطاق التنفيذ والضمان في حقل نطاق العمل.</div>${quotePartsPicker(savedParts)}</div>`);
    }
    f?.querySelectorAll('[name^="spec_"]').forEach(field=>{
      const key=String(field.name||"").replace(/^spec_/,""),label=field.closest("label");
      if(label&&!maintenanceSpecKeys.has(key))label.style.display=isInstall?"":"none";
    });
    f?.querySelectorAll(".parts-contract-mode").forEach(x=>x.style.display=isParts?"":"none");
    f?.querySelectorAll(".maintenance-mode-full,.maintenance-mode-install").forEach(x=>x.style.display=isParts?"none":x.style.display);
    if(isParts&&panels.length&&f.dataset.contractTabsMode!=="parts"){
      const tabBar=Array.from(f.children).find(x=>x.classList?.contains("contract-tabs"));
      if(tabBar)tabBar.innerHTML='<button type="button" class="contract-tab active" data-contract-tab="0">البيانات الأساسية</button><button type="button" class="contract-tab" data-contract-tab="1">قطع الغيار ونطاق العمل</button>';
      panels.forEach((panel,index)=>{const last=index===panels.length-1;panel.dataset.contractTabPanel=last?"1":"0";panel.style.display=(index===0||last)?"":"none";panel.classList.toggle("active",index===0)});
      f.dataset.contractTabsMode="parts";
    }
  };

  function maintenanceContractPartyData(c){
    const co=activeOwnerCompany()||{},company=c.company?.name||co.name||"شركة غير محددة";
    const partyOneId=[co.unifiedNumber?`الرقم الموحد: ${co.unifiedNumber}`:"",co.commercialNumber?`السجل التجاري: ${co.commercialNumber}`:""].filter(Boolean).join(" — ")||"—";
    const partyTwoId=[c.clientCompanyUnifiedNumber?`الرقم الموحد: ${c.clientCompanyUnifiedNumber}`:"",c.clientId?`رقم الهوية: ${c.clientId}`:""].filter(Boolean).join(" — ")||"—";
    const partyTwoName=c.clientCompanyName&&c.clientName?`${c.clientCompanyName} / ${c.clientName}`:contractLabel(c);
    return [
      {side:"الطرف الأول",name:company,id:partyOneId,contact:[co.phone,co.address].filter(Boolean).join(" — ")||"—"},
      {side:"الطرف الثاني",name:partyTwoName,id:partyTwoId,contact:c.clientPhone||"—"}
    ];
  }

  function maintenanceContractPartiesTable(c){
    const rows=maintenanceContractPartyData(c);
    return `<table class="contract-spec-table maintenance-contract-parties"><colgroup><col style="width:14%"><col style="width:24%"><col style="width:28%"><col style="width:34%"></colgroup><thead><tr><th>الطرف</th><th>الاسم / المنشأة</th><th>الهوية / الرقم الموحد</th><th>التواصل / العنوان</th></tr></thead><tbody>${rows.map(row=>`<tr><th>${esc(row.side)}</th><td>${esc(row.name)}</td><td>${esc(row.id)}</td><td>${esc(row.contact)}</td></tr>`).join("")}</tbody></table>`;
  }

  function maintenanceHorizontalTables(rows,columns=4,className=""){
    const chunks=[];
    for(let index=0;index<rows.length;index+=columns)chunks.push(rows.slice(index,index+columns));
    return `<div class="maintenance-horizontal-tables ${className}">${chunks.map(chunk=>`<table class="contract-spec-table maintenance-horizontal-table"><thead><tr>${chunk.map(row=>`<th>${esc(row[0])}</th>`).join("")}</tr></thead><tbody><tr>${chunk.map(row=>`<td>${esc(row[1])}</td>`).join("")}</tr></tbody></table>`).join("")}</div>`;
  }

  function maintenanceContractSpecsSection(info={}){
    const source=info&&typeof info==="object"?info:{},seen=new Set(),fields=[["count","عدد المصاعد"],...specGroups.flatMap(group=>(group.fields||[]).filter(field=>maintenanceSpecKeys.has(field[0])).map(field=>[field[0],field[1]]))];
    const rows=fields.filter(([key])=>{if(seen.has(key))return false;seen.add(key);return String(source[key]??"").trim()!==""}).map(([key,label])=>[label,source[key]]);
    const content=rows.length?maintenanceHorizontalTables(rows,4,"maintenance-contract-specs"):`<p class="form-note decision-note">مواصفات المصعد غير موجودة في بيانات هذا العقد، ويلزم استعادتها من نسخة موثوقة قبل اعتماد المستند.</p>`;
    return `<section class="contract-section" data-maintenance-contract-section="specifications"><h3>ثانياً: مواصفات المصعد</h3>${content}</section>`;
  }

  function contractPaymentMethods(c){
    const methods=financialEntries.filter(entry=>entry.contractId===c?.id&&entry.direction==="in"&&entry.paymentMethod).map(entry=>String(entry.paymentMethod).trim()).filter(Boolean);
    return [...new Set(methods)].join("، ")||"لم تسجل دفعات بعد";
  }

  function maintenanceContractDetails(c){
    const company=c.company?.name||activeOwnerCompany()?.name||"شركة غير محددة";
    const basicRows=[
      ["رقم العقد",c.id||"—"],["حالة العقد",c.status||"—"],["بداية العقد",c.startDate||"غير محدد"],["نهاية العقد",c.endDate||"غير محدد"],
      ["مدة العقد",`${Number(c.contractYears||1)} سنة`],["قيمة العقد",money(c.value)],["طريقة الدفع",contractPaymentMethods(c)],["منشأة الإصدار",company]
    ];
    const buildings=(c.buildings||[]).length?`<h4 class="maintenance-contract-subtitle">المباني والمواقع</h4><table class="contract-spec-table maintenance-contract-locations"><colgroup><col style="width:20%"><col style="width:15%"><col style="width:15%"><col style="width:20%"><col style="width:30%"></colgroup><thead><tr><th>المبنى</th><th>الحي</th><th>رقم المبنى</th><th>جوال المسؤول</th><th>رابط الخريطة</th></tr></thead><tbody>${c.buildings.map(b=>`<tr><td>${esc(b.name||"غير محدد")}</td><td>${esc(b.district||"—")}</td><td>${esc(b.buildingNumber||"—")}</td><td>${esc(b.guardMobile||"—")}</td><td>${esc(b.mapUrl||"—")}</td></tr>`).join("")}</tbody></table>`:"";
    const scope=esc(c.details||"يشمل العقد أعمال الصيانة الدورية للمصعد وفق البنود المحددة للحفاظ على سلامته وأدائه طوال مدة العقد.");
    const defaultTerms=(c.items||[]).length?`<h4 class="maintenance-contract-subtitle">بنود الصيانة المعتمدة</h4>${renderTerms(c.items,"")}`:"";
    const customTerms=(c.customItems||[]).length?`<h4 class="maintenance-contract-subtitle">بنود الصيانة الإضافية</h4>${renderTerms(c.customItems,"")}`:"";
    return `<style>.maintenance-contract [data-maintenance-contract-section]{break-inside:auto;page-break-inside:auto}.maintenance-contract [data-maintenance-contract-section]>h3{break-after:avoid;page-break-after:avoid}.maintenance-contract .maintenance-contract-parties,.maintenance-contract .maintenance-horizontal-table{break-inside:avoid;page-break-inside:avoid}.maintenance-contract .maintenance-contract-parties th,.maintenance-contract .maintenance-contract-locations th,.maintenance-contract .maintenance-horizontal-table th{width:auto;white-space:normal}.maintenance-contract .maintenance-horizontal-table{margin:0 0 8px}.maintenance-contract .maintenance-horizontal-table th,.maintenance-contract .maintenance-horizontal-table td{text-align:center;vertical-align:middle}.maintenance-contract .maintenance-horizontal-table td{font-weight:700}.maintenance-contract .maintenance-contract-subtitle{margin:14px 0 6px;color:#c9964b;break-after:avoid;page-break-after:avoid}.maintenance-contract .contract-spec-table thead{display:table-header-group}.maintenance-contract .contract-spec-table tr{break-inside:avoid;page-break-inside:avoid}</style><div class="contract-document maintenance-contract"><div class="contract-topline"><span class="contract-type">عقد صيانة</span>${badge(c.status)}</div><div class="contract-number-strip"><span>رقم العقد</span><b>${esc(c.id)}</b></div><section class="contract-section" data-maintenance-contract-section="basic"><h3>أولاً: البيانات الأساسية</h3><h4 class="maintenance-contract-subtitle">بيانات أطراف العقد</h4>${maintenanceContractPartiesTable(c)}<h4 class="maintenance-contract-subtitle">بيانات العقد</h4>${maintenanceHorizontalTables(basicRows,4,"maintenance-contract-basic")}${buildings}${c.financialNotes?`<h4 class="maintenance-contract-subtitle">ملاحظات مالية</h4><p>${esc(c.financialNotes)}</p>`:""}</section>${maintenanceContractSpecsSection(c.elevatorInfo)}<section class="contract-section" data-maintenance-contract-section="maintenance"><h3>ثالثاً: الصيانة</h3><h4 class="maintenance-contract-subtitle">نطاق الصيانة</h4><p>${scope}</p><h4 class="maintenance-contract-subtitle">عدد الزيارات</h4><p>اثنتا عشرة (12) زيارة دورية خلال مدة العقد.</p><h4 class="maintenance-contract-subtitle">بنود الصيانة الدورية</h4>${renderMaintenanceChecklist(c.maintenanceChecklist)}${defaultTerms}${customTerms}</section>${signatureArea(c,c.companyOwnerId)}</div>`;
  }

  function partsContractDetails(c){
    const rows=(c.partsItems?.length?c.partsItems:(c.customItems||[]).filter(x=>x.section==="قطع الغيار"));
    const partsHtml=rows.length?`<table class="contract-spec-table"><thead><tr><th>القطعة</th><th>الكمية</th><th>سعر الوحدة</th><th>الإجمالي</th><th>البيان</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.title||x.name||"—")}</td><td>${esc(x.qty||1)}</td><td>${money(x.unitPrice||0)}</td><td>${money(x.price||0)}</td><td>${esc(x.description||"—")}</td></tr>`).join("")}</tbody></table>`:'<p class="form-note decision-note">لم تُسجل قطع غيار في هذا العقد.</p>';
    const buildings=(c.buildings||[]).map(b=>`${esc(b.name||"غير محدد")} - ${esc(b.district||"—")}`).join("<br>")||"غير محدد";
    return `<div class="contract-document"><div class="contract-topline"><span class="contract-type">عقد توريد وتركيب قطع غيار</span>${badge(c.status)}</div><div class="contract-number-strip"><span>رقم العقد</span><b>${esc(c.id)}</b></div><div class="contract-summary"><div><small>الطرف الثاني</small><b>${esc(contractLabel(c))}</b></div><div><small>قيمة العقد</small><b>${money(c.value)}</b></div><div><small>تاريخ البداية</small><b>${esc(c.startDate||"—")}</b></div><div><small>طريقة الدفع</small><b>${esc(contractPaymentMethods(c))}</b></div><div><small>موقع التنفيذ</small><b>${buildings}</b></div><div><small>حالة العقد</small><b>${esc(c.status||"—")}</b></div></div><section class="contract-section"><h3>قطع الغيار والكميات</h3>${partsHtml}</section><section class="contract-section"><h3>نطاق التوريد والتركيب</h3><p>${esc(c.details||"يشمل العقد توريد القطع المعتمدة وتركيبها وضبطها واختبارها وتسليم المصعد بحالة تشغيلية سليمة.")}</p></section><section class="contract-section"><h3>الضمان والاستلام</h3><p>تخضع القطع وأعمال التركيب للضمان المثبت في العرض أو بيانات المورد، ويبدأ الضمان من تاريخ الاستلام والتشغيل، ولا يشمل سوء الاستخدام أو العبث.</p></section>${signatureArea(c,c.companyOwnerId)}</div>`;
  }

  const fullContractDetails=contractDetails;
