  function myLocationPage(){const loc=locations.find(l=>cleanId(l.identity)===cleanId(session.id));const live=localStorage.getItem(`misadLiveLocation:${session.id}`)==="on"&&loc?.live&&Date.now()-(loc.updatedAtMs||0)<45000;return `${head("موقعي المباشر","مشاركة مباشرة تتغير مع تغير موقع الفني",'<button class="btn-primary" data-start-live-location>بدء مشاركة الموقع المباشر</button> <button class="btn" data-stop-live-location>إيقاف المشاركة</button> <button class="btn-primary" data-update-location>تحديث مرة واحدة</button>')}<div class="dashboard-grid"><section class="panel"><h3>الحالة</h3><p>${live?"مباشر ويتم تحديثه كل 10 ثوانٍ":"متوقف"}</p><p>${loc?`آخر تحديث: ${fmtDate(loc.updatedAtIso)}`:"لم يحفظ موقع بعد"}</p>${loc?mapLink(loc.mapUrl):""}</section><section class="panel tracking-map-panel"><iframe class="tracking-map" src="${mapEmbed(loc?.mapUrl)}"></iframe></section></div>`}
